import{_ as t,K as l,a as r,c as o,b as a,k as s,q as p,ac as n}from"./chunks/framework.BSuaGltH.js";const C=JSON.parse('{"title":"围棋：连接、断点与基本吃子技巧","description":"从共享气出发，学会看直接连接、斜连和打吃，并判断一手棋能否真正救出棋块。","frontmatter":{"title":"围棋：连接、断点与基本吃子技巧","description":"从共享气出发，学会看直接连接、斜连和打吃，并判断一手棋能否真正救出棋块。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"围棋入门","summary":"从共享气出发，学会看直接连接、斜连和打吃，并判断一手棋能否真正救出棋块。","status":"active","related":[{"title":"围棋：落子、气、提子与胜负计算","link":"/life/personal/chess/weiqi/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：眼、死活与简单对杀","link":"/life/personal/chess/weiqi/life-death","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：从布局到收官的一盘棋复盘","link":"/life/personal/chess/weiqi/review","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"围棋：落子、气、提子与胜负计算","link":"/life/personal/chess/weiqi/rules"},"next":{"text":"围棋：眼、死活与简单对杀","link":"/life/personal/chess/weiqi/life-death"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"围棋：落子、气、提子与胜负计算","link":"/life/personal/chess/weiqi/rules"},"next":{"text":"围棋：眼、死活与简单对杀","link":"/life/personal/chess/weiqi/life-death"}},"headers":[],"relativePath":"life/personal/chess/weiqi/connections.md","filePath":"life/personal/chess/weiqi/connections.md"}'),c={name:"life/personal/chess/weiqi/connections.md"},d={class:"chess-example"},h={class:"chess-figure"};function g(f,e,u,_,m,k){const i=l("ArticleImage");return r(),o("div",null,[e[1]||(e[1]=a("h1",{id:"围棋-连接、断点与基本吃子技巧",tabindex:"-1"},[s("围棋：连接、断点与基本吃子技巧 "),a("a",{class:"header-anchor",href:"#围棋-连接、断点与基本吃子技巧","aria-label":'Permalink to "围棋：连接、断点与基本吃子技巧"'},"​")],-1)),e[2]||(e[2]=a("p",null,"连接的意义，是让几颗棋共同承担生存压力。吃子的前提，是让对方一串棋没有气。这两件事都从数气开始，不从“看起来连着”开始。",-1)),e[3]||(e[3]=a("h2",{id:"直接连接和斜连不同",tabindex:"-1"},[s("直接连接和斜连不同 "),a("a",{class:"header-anchor",href:"#直接连接和斜连不同","aria-label":'Permalink to "直接连接和斜连不同"'},"​")],-1)),a("div",d,[a("div",h,[a("p",null,[p(i,{src:"/images/chess/weiqi-connect.svg",alt:"直接连接 · 三子一串。B2 → C2 → C3 连通；斜邻本身不算连接。"})])]),e[0]||(e[0]=n(`<div class="chess-explanation"><p>本文坐标 A～I 从左到右、1～9 从下到上。黑 X、白 O，<code>.</code> 为空。下面 B2 与 C2 是直接连接，C3 的黑子也通过 C2 加入同一串。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4  . . . . .</span></span>
<span class="line"><span>3  . . X . .</span></span>
<span class="line"><span>2  . X X . .</span></span>
<span class="line"><span>1  . . . . .</span></span>
<span class="line"><span>   A B C D E</span></span></code></pre></div><p>若拿掉 C2，只剩 B2、C3，它们斜着相邻，却是两串独立棋。B3、C2 是附近的连接要点。对手在其中一个点落子，能限制连接；但不能只凭这一颗就断言已经成功切断，还要看另一个点能不能补上，以及周边的气。</p><p>“断点”就是对方可能利用来分开己方棋的位置。先问被断开的两边能不能各自活；如果都很安全，不必每个断点都机械地补。</p></div>`,1))]),e[4]||(e[4]=n('<h2 id="打吃要知道对方往哪跑" tabindex="-1">打吃要知道对方往哪跑 <a class="header-anchor" href="#打吃要知道对方往哪跑" aria-label="Permalink to &quot;打吃要知道对方往哪跑&quot;">​</a></h2><p>摆黑子 B2，白子 A2、B1、C2，轮黑走。黑只有 B3 一口气。</p><p>黑下 B3 后，黑 B2、B3 连接。B2 原来的三面被白占住，新增气为 A3、C3、B4，共三口。对白方来说，立刻只占其中一口并不能马上提掉整串。原来的一子从“一气”变成了两子“三气”。</p><p>再增加白子 A3、C3、B4，仍轮黑走。此时 B3 虽然是空点，但黑下 B3 后整串没有气，又提不掉白棋，按本文规则不合法。<strong>能不能逃，取决于逃出去之后的局面。</strong></p><h2 id="不要把对方打强" tabindex="-1">不要把对方打强 <a class="header-anchor" href="#不要把对方打强" aria-label="Permalink to &quot;不要把对方打强&quot;">​</a></h2><p>你连续打吃，对方每次顺势向外长，可能从一颗危险孤子变成一条很有力量的棋。打吃不是天然的好棋；要看它把对方赶向哪里。</p><p>选择打吃方向时，可以按顺序问：对方若逃，会靠近自己的弱棋吗？我是否把对方赶向己方厚实区域？我能否封住去路？如果答案都不清楚，先补自己的断点，通常比追着打更容易理解。</p><h2 id="征子和枷先认识目的" tabindex="-1">征子和枷先认识目的 <a class="header-anchor" href="#征子和枷先认识目的" aria-label="Permalink to &quot;征子和枷先认识目的&quot;">​</a></h2><p>征子是连续打吃，把对方逼成弯折逃跑的路线；通常每次只剩一口气。不能只记“征子一定吃”，路上遇到对方接应子，结果可能改变。枷则是先在外面封住，不急着紧贴打吃。</p><p>刚入门可以先不背复杂征子变化。拿一块棋在实物棋盘上逐步摆，每走一步都重新数气；不要凭脑中模糊的锯齿形状认定能吃。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li>图中 B2、C2、C3 黑棋是否共享所有气？<strong>共享。</strong> 因为存在上下左右的连接路径。</li><li>删除 C2 后，白下 B3，黑还可能怎样连接？<strong>考虑 C2。</strong> 但要检查这个点的气和周围白棋，不能无条件说能接上。</li><li>本文第一种逃跑例中黑下 B3 后有几口气？<strong>三口。</strong> A3、C3、B4；B3 已被占，不再是气。</li></ol><p>练习时把气用铅笔圈出来，每一个空点只圈一次。数错气往往比不会某个术语更早决定胜负。</p><p>规则参考：<a href="https://www.britgo.org/intro/intro2.html" target="_blank" rel="noopener noreferrer">英国围棋协会入门</a>。局部摆法及分析为原创练习。</p>',14))])}const b=t(c,[["render",g]]);export{C as __pageData,b as default};
